/*
 * A305055  Numbers n such that the z-density of the integer partition with
 *          Heinz number n is 0.
 * https://oeis.org/A305055
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 45, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A305055
 *  Numbers n such that the z‑density of the integer partition
 *  with Heinz number n is 0.
 *  The sequence is generated by searching the integers in
 *  increasing order and selecting those whose prime‑factorisation
 *  satisfies the z‑density condition.
 *
 *  The implementation uses a pre‑computed sieve up to 20 000 000
 *  to obtain primes and their indices.  For each candidate n the
 *  following checks are performed:
 *
 *   1. Factor n into distinct primes p_i with multiplicities e_i.
 *   2. For each prime factor p_i let j_i = π(p_i) be the index
 *      of the prime in the sequence of all primes.
 *   3. Let ω(j) be the number of distinct prime factors of the
 *      integer j.  We pre‑compute ω(j) for all j up to the
 *      maximal prime index.
 *   4. For the multiset of indices S = {j_i}:
 *        sum_ω = Σ e_i·ω(j_i)       (total of ω(j) with multiplicity)
 *        |S|   = Σ e_i              (number of parts)
 *     The z‑density of S is zero iff
 *        sum_ω – |S|  =  #{distinct primes dividing any j in S}.
 *
 *  The latter “number of distinct primes” is obtained by
 *  union‑ing the prime factorizations of the distinct indices
 *  j.  All necessary factorizations are available from
 *  the pre‑computed smallest prime factor table for
 *  integers up to the prime‑count.
 *
 *  The sequence values are cached in a dynamically grown
 *  array so repeated calls to a(n) are efficient and work
 *  in any order.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

/* ------------------------------------------------------------- */
/*  Constants and global tables                                  */
/* ------------------------------------------------------------- */

#define MAX_LIMIT 20000000U          /* sieve bound (must be > all primes used) */
#define MAX_PRIMES 1300000U          /* sufficient for primes up to MAX_LIMIT */

static uint8_t  is_composite[MAX_LIMIT + 1];
static uint32_t pi_of_prime[MAX_LIMIT + 1];     /* prime → 1‑based index, 0 if composite */
static uint32_t primes[MAX_PRIMES];
static size_t   prime_count = 0;

static uint32_t *spf_small   = NULL;   /* SPF for numbers up to prime_count */
static uint32_t *omega_of_j  = NULL;   /* ω(j) for j ≤ prime_count */
static uint32_t *seenJ       = NULL;   /* timestamp table for distinct indices j */
static uint32_t *visitedPrime= NULL;   /* timestamp table for primes dividing any j */

static bool init_done = false;

/* ------------------------------------------------------------- */
/*  Initialisation routine                                         */
/* ------------------------------------------------------------- */

static void init_primes(void)
{
    if (init_done) return;
    init_done = true;

    /* Simple sieve of Eratosthenes up to MAX_LIMIT */
    prime_count = 0;
    for (uint32_t i = 2; i <= MAX_LIMIT; ++i)
    {
        if (!is_composite[i])
        {
            if (prime_count >= MAX_PRIMES) break;
            primes[prime_count++] = i;
            pi_of_prime[i] = (uint32_t)(prime_count);   /* 1‑based index */
            if ((uint64_t)i * i <= MAX_LIMIT)
                for (uint32_t j = i * i; j <= MAX_LIMIT; j += i)
                    is_composite[j] = 1;
        }
    }

    /* Allocate dynamic arrays for prime indices up to prime_count  */
    spf_small   = (uint32_t*)malloc(sizeof(uint32_t) * (prime_count + 1));
    omega_of_j  = (uint32_t*)malloc(sizeof(uint32_t) * (prime_count + 1));
    seenJ       = (uint32_t*)malloc(sizeof(uint32_t) * (prime_count + 1));
    visitedPrime= (uint32_t*)malloc(sizeof(uint32_t) * (prime_count + 1));
    if (!spf_small || !omega_of_j || !seenJ || !visitedPrime)
        exit(1);                                     /* Out of memory */

    /* Compute SPF for numbers up to prime_count (linear sieve) */
    memset(spf_small, 0, sizeof(uint32_t) * (prime_count + 1));
    for (uint32_t i = 2; i <= prime_count; ++i)
    {
        if (spf_small[i] == 0)
        {
            spf_small[i] = i;
            if ((uint64_t)i * i <= prime_count)
                for (uint32_t j = i * i; j <= prime_count; j += i)
                    if (spf_small[j] == 0) spf_small[j] = i;
        }
    }

    /* Compute ω(j) for j ≤ prime_count  */
    omega_of_j[0] = 0;
    omega_of_j[1] = 0;
    for (uint32_t i = 2; i <= prime_count; ++i)
    {
        uint32_t x = i, cnt = 0;
        while (x > 1)
        {
            uint32_t pf = spf_small[x];
            ++cnt;
            while (x % pf == 0) x /= pf;
        }
        omega_of_j[i] = cnt;
    }

    /* initialise timestamp tables  */
    memset(seenJ, 0, sizeof(uint32_t) * (prime_count + 1));
    memset(visitedPrime, 0, sizeof(uint32_t) * (prime_count + 1));
}

/* ------------------------------------------------------------- */
/*  Z‑density test for a candidate number                         */
/* ------------------------------------------------------------- */

static uint32_t cur_mark_seenJ     = 1;
static uint32_t cur_mark_prime_vis = 1;

static bool passes_zdensity_zero(uint64_t val)
{
    if (val == 1) return true;           /* empty partition */

    uint64_t temp = val;
    uint32_t sum_omega = 0;              /* Σ e·ω(j)  */
    uint32_t size_S    = 0;              /* Σ e   (number of parts) */
    uint32_t distinct_js[64];            /* unique indices j (max at 64) */
    uint32_t distinct_len = 0;

    /* -----------------  factorisation of val  ----------------- */
    for (size_t k = 0; k < prime_count; ++k)
    {
        uint32_t p = primes[k];
        if ((uint64_t)p * p > temp) break;
        if (temp % p == 0)
        {
            uint32_t cnt = 0;
            while (temp % p == 0) { temp /= p; ++cnt; }
            size_S += cnt;
            uint32_t j = pi_of_prime[p];
            sum_omega += cnt * omega_of_j[j];
            if (seenJ[j] != cur_mark_seenJ)
            {
                seenJ[j] = cur_mark_seenJ;
                distinct_js[distinct_len++] = j;
            }
        }
    }

    if (temp > 1)          /* remaining prime factor > sqrt(original) */
    {
        uint64_t p = temp;
        size_S += 1;
        uint32_t j = pi_of_prime[(uint32_t)p];
        sum_omega += omega_of_j[j];
        if (seenJ[j] != cur_mark_seenJ)
        {
            seenJ[j] = cur_mark_seenJ;
            distinct_js[distinct_len++] = j;
        }
    }

    /* -------------  count distinct primes of all j  --------------- */
    uint32_t unique_prime_count = 0;
    for (uint32_t idx = 0; idx < distinct_len; ++idx)
    {
        uint32_t j = distinct_js[idx];
        uint32_t x = j;
        while (x > 1)
        {
            uint32_t pf = spf_small[x];
            if (visitedPrime[pf] != cur_mark_prime_vis)
            {
                visitedPrime[pf] = cur_mark_prime_vis;
                ++unique_prime_count;
            }
            while (x % pf == 0) x /= pf;
        }
    }

    /* advance timestamp marks for next candidate */
    ++cur_mark_seenJ;
    ++cur_mark_prime_vis;

    return (sum_omega - size_S) == unique_prime_count;
}

/* ------------------------------------------------------------- */
/*  Sequence cache                                                 */
/* ------------------------------------------------------------- */

static seq_t *term_cache = NULL;
static size_t term_len   = 0;
static size_t term_cap   = 0;
static uint64_t current_candidate = 1;

/* ------------------------------------------------------------- */
/*  Main sequence function                                       */
/* ------------------------------------------------------------- */

seq_t a(idx_t n)
{
    if (n == 0) return 0;

    init_primes();

    /* extend cache until we have at least n terms */
    while (term_len < n)
    {
        if (passes_zdensity_zero(current_candidate))
        {
            if (term_len == term_cap)
            {
                term_cap = term_cap ? term_cap << 1 : 64;
                term_cache = (seq_t*)realloc(term_cache, term_cap * sizeof(seq_t));
                if (!term_cache) exit(1);
            }
            term_cache[term_len++] = (seq_t)current_candidate;
        }
        ++current_candidate;
    }

    return term_cache[n - 1];
}
